window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7acf61c8a20ec5d0"]={"versions": [{"id": "FIG-7acf61c8a20ec5d0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein AUTOSAR-Methodik-Aktivitätendiagramm (Work Flow Overview) gemäß AUTOSAR_TR_Methodology. Es visualisiert den übergeordneten Entwicklungsablauf der AUTOSAR Classic Platform auf System-, Subsystem- und Steuergeräteebene. Dargestellt sind Entwicklungsaktivitäten (Tasks/Activities) und deren datenbezogene Ein- und Ausgangsartefakte (Work Products / XML-Beschreibungen nach AUTOSAR-Metamodell) samt Kardinalitäten und Stereotypen («input», «output»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernentitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Develop a VFB System Description</code>: Erzeugt aus Vorgaben die virtuelle Funktionsbus-Systembeschreibung.</li>\n<li><code>Develop System</code>: Definiert die Gesamt-Systemarchitektur und -verteilung.</li>\n<li><code>Develop Sub-System</code>: Zerlegt Systemextrakte weiter auf Subsystemebene.</li>\n<li><code>Develop Application Software</code>: Erstellt anwendungsspezifische Softwarekomponenten.</li>\n<li><code>Develop Basic Software</code>: Konfiguriert und generiert basisbezogene Softwaremodule.</li>\n<li><code>Integrate Software for ECU</code>: Führt alle software- und steuergerätespezifischen Artefakte auf ECU-Ebene zusammen.</li>\n<li><strong>Artefakte und Schnittstellenbeziehungen</strong>:</li>\n<li><code>Standard Package</code>: Dient als Eingangsartefakt (<code>1..* «input»</code>) für <code>Develop a VFB System Description</code>.</li>\n<li><code>BSW Standard Package</code>: Dient als Eingangsartefakt (<code>1 «input»</code>) für <code>Develop Basic Software</code>.</li>\n<li><code>Overall VFB System</code>: Ausgang von <code>Develop a VFB System Description</code> (<code>«output» 1</code>); dient als Eingang für <code>Develop System</code> (<code>0..1 «input»</code>) und für <code>Develop Application Software</code> (<code>1 «input»</code>).</li>\n<li><code>System Constraint Description</code>: Optionales Eingangsartefakt (<code>0..1 «input»</code>) für <code>Develop System</code>.</li>\n<li><code>System Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 1..*</code>); dient als Eingang (<code>1 «input»</code>) für <code>Develop Sub-System</code>.</li>\n<li><code>ECU Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 1..<em></code>) sowie von <code>Develop Sub-System</code> (<code>«output» 1..</em></code>); dient als Eingang (<code>1 «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>Delivered Atomic Software Components</code>: Ausgang von <code>Develop Application Software</code> (<code>«output» 1..<em></code>); dient als Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>BSW Module Delivered Bundle</code>: Ausgang von <code>Develop Basic Software</code> (<code>«output» 1..<em></code>); dient als Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>ECU Software</code>: Finales Ausgangsartefakt (<code>«output» 1</code>) von <code>Integrate Software for ECU</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Entwicklungsablauf gliedert sich in folgende Sequenzphasen:</p>\n<ol class=\"fig-list\">\n<li><strong>System- und VFB-Definition</strong>: Auf Basis von <code>Standard Package</code> erstellt <code>Develop a VFB System Description</code> das <code>Overall VFB System</code>.</li>\n<li><strong>Systemdesign und Partitionierung</strong>: <code>Develop System</code> konsolidiert optional <code>System Constraint Description</code> sowie das <code>Overall VFB System</code> und leitet daraus <code>System Extract</code> (für Subsysteme) sowie <code>ECU Extract</code> (für direkte Steuergeräteintegration) ab. <code>Develop Sub-System</code> verfeinert <code>System Extract</code> zu weiteren <code>ECU Extract</code>-Instanzen.</li>\n<li><strong>Parallele Komponenten- und Basissoftwareentwicklung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Develop Application Software</code> nutzt <code>Overall VFB System</code> zur Erzeugung von <code>Delivered Atomic Software Components</code>.</li>\n<li><code>Develop Basic Software</code> erzeugt aus <code>BSW Standard Package</code> das <code>BSW Module Delivered Bundle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU-Integration</strong>: <code>Integrate Software for ECU</code> aggregiert mindestens einen <code>ECU Extract</code>, mindestens ein <code>BSW Module Delivered Bundle</code> und mindestens ein Bundle <code>Delivered Atomic Software Components</code> zur finalen <code>ECU Software</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Mindestanforderungen für Toolketten und Rollenmodelle im AUTOSAR-Entwicklungsprozess. Werkzeuge müssen den Austausch der standardisierten ARXML-Formate unterstützen. Kardinalitäten legen fest, welche Vorbedingungen für die Ausführung nachgelagerter Schritte zwingend erfüllt sein müssen (z. B. mindestens ein ECU-Extrakt sowie mindestens ein BSW- und SWC-Lieferbundle für die ECU-Integration). Optionale Artefakte (Multiplizität <code>0..1</code>) gestatten Flexibilität beim initialen Systemdesign und bei Randbedingungen.</p>"}, {"id": "FIG-ebbda13bbb22d49c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein AUTOSAR-Methodik-Aktivitätendiagramm (Work Flow Overview) gemäß AUTOSAR_TR_Methodology. Es visualisiert den übergeordneten Entwicklungsablauf der AUTOSAR Classic Platform auf System-, Subsystem- und Steuergeräteebene. Dargestellt sind Entwicklungsaktivitäten (Tasks/Activities) und deren datenbezogene Ein- und Ausgangsartefakte (Work Products / XML-Beschreibungen nach AUTOSAR-Metamodell) samt Kardinalitäten und Stereotypen («input», «output»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernentitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Develop System Description</code> (oben mittig): Erstellt aus Standardvorgaben und System-Constraints eine abstrakte Systembeschreibung.</li>\n<li><code>Develop System Description</code> (oben rechts): Erzeugt basierend auf Standardpaketen und optionalen abstrakten Systembeschreibungen die VFB-Gesamtbeschreibung.</li>\n<li><code>Develop System</code>: Definiert die Gesamt-Systemarchitektur und -verteilung.</li>\n<li><code>Develop Sub-System</code>: Zerlegt Systemextrakte weiter auf Subsystemebene.</li>\n<li><code>Develop Application Software</code>: Erstellt anwendungsspezifische Softwarekomponenten.</li>\n<li><code>Develop Basic Software</code>: Konfiguriert und generiert basisbezogene Softwaremodule.</li>\n<li><code>Integrate Software for ECU</code>: Führt alle software- und steuergerätespezifischen Artefakte auf ECU-Ebene zusammen.</li>\n<li><strong>Artefakte und Schnittstellenbeziehungen</strong>:</li>\n<li><code>Standard Package</code>: Dient als Eingang (<code>1..* «input»</code>) für <code>Develop System Description</code> (oben mittig) und für <code>Develop System Description</code> (oben rechts).</li>\n<li><code>BSW Standard Package</code>: Dient als Eingang (<code>1 «input»</code>) für <code>Develop Basic Software</code>.</li>\n<li><code>System Constraint Description</code>: Dient als optionaler Eingang (<code>0..1 «input»</code>) für <code>Develop System Description</code> (oben mittig) sowie für <code>Develop System</code> (<code>0..1 «input»</code>).</li>\n<li><code>Abstract System Description</code>: Ausgang von <code>Develop System Description</code> (oben mittig, <code>«output» 1..<em></code>); dient als optionaler/mehrfacher Eingang (<code>0..</em> «input»</code>) für <code>Develop System Description</code> (oben rechts) und für <code>Develop System</code> (<code>0..* «input»</code>).</li>\n<li><code>Overall VFB System</code>: Ausgang von <code>Develop System Description</code> (oben rechts, <code>«output» 1</code>); dient als optionaler Eingang (<code>0..1 «input»</code>) für <code>Develop System</code> und als Eingang (<code>1 «input»</code>) für <code>Develop Application Software</code>.</li>\n<li><code>System Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 0..*</code>); dient als Eingang (<code>1 «input»</code>) für <code>Develop Sub-System</code>.</li>\n<li><code>ECU Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 1..<em></code>) sowie von <code>Develop Sub-System</code> (<code>«output» 1..</em></code>); dient als Eingang (<code>1 «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>Delivered Atomic Software Components</code>: Ausgang von <code>Develop Application Software</code> (<code>«output» 1..<em></code>); dient als Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>BSW Module Delivered Bundle</code>: Ausgang von <code>Develop Basic Software</code> (<code>«output» 1..<em></code>); dient als Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>ECU Software</code>: Finales Ausgangsartefakt (<code>«output» 1</code>) von <code>Integrate Software for ECU</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Entwicklungsablauf gliedert sich in folgende Sequenzphasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Systembeschreibungs- und VFB-Definition</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Develop System Description</code> (oben mittig) verarbeitet <code>Standard Package</code> und optional <code>System Constraint Description</code> zu mindestens einer <code>Abstract System Description</code>.</li>\n<li><code>Develop System Description</code> (oben rechts) verarbeitet <code>Standard Package</code> und optional <code>Abstract System Description</code> zum <code>Overall VFB System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Systemdesign und Partitionierung</strong>: <code>Develop System</code> führt optional <code>Abstract System Description</code>, <code>System Constraint Description</code> und <code>Overall VFB System</code> zusammen und leitet daraus null bis mehrere <code>System Extract</code>-Artefakte sowie mindestens einen <code>ECU Extract</code> ab. <code>Develop Sub-System</code> verfeinert vorhandene <code>System Extract</code>-Artefakte zu weiteren <code>ECU Extract</code>-Instanzen.</li>\n<li><strong>Parallele Komponenten- und Basissoftwareentwicklung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Develop Application Software</code> generiert aus dem <code>Overall VFB System</code> atomare Softwarekomponenten (<code>Delivered Atomic Software Components</code>).</li>\n<li><code>Develop Basic Software</code> erzeugt aus <code>BSW Standard Package</code> das <code>BSW Module Delivered Bundle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU-Integration</strong>: <code>Integrate Software for ECU</code> führt <code>ECU Extract</code>, <code>BSW Module Delivered Bundle</code> und <code>Delivered Atomic Software Components</code> zur <code>ECU Software</code> zusammen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik unterstützt durch die Einführung der <code>Abstract System Description</code> eine gestufte Systemmodellierung vor der Festlegung auf eine konkrete VFB-Topologie. Kardinalitäten wie <code>0..*</code> für <code>System Extract</code> erlauben Architekturen ohne Subsystem-Zerlegung, sodass Systeme direkt in <code>ECU Extract</code>-Artefakte übergehen können. Toolketten müssen die optionale Verkettung über abstrakte Systembeschreibungen sowie die direkte oder gestufte Systemextraktion abbilden können.</p>"}, {"id": "FIG-8db5103d6653e15c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein AUTOSAR-Methodik-Aktivitätendiagramm (Work Flow Overview) gemäß AUTOSAR_TR_Methodology. Es visualisiert den übergeordneten Entwicklungsablauf der AUTOSAR Classic Platform auf System-, Subsystem- und Steuergeräteebene. Dargestellt sind Entwicklungsaktivitäten (Tasks/Activities) und deren datenbezogene Ein- und Ausgangsartefakte (Work Products / XML-Beschreibungen nach AUTOSAR-Metamodell) samt Kardinalitäten und Stereotypen («input», «output»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Kernentitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Develop System Description</code> (oben mittig): Erstellt aus Standardvorgaben und System-Constraints eine abstrakte Systembeschreibung.</li>\n<li><code>Develop System Description</code> (oben rechts): Erzeugt basierend auf Standardpaketen und optionalen abstrakten Systembeschreibungen die VFB-Gesamtbeschreibung.</li>\n<li><code>Develop System</code>: Definiert die Gesamt-Systemarchitektur und -verteilung.</li>\n<li><code>Develop Sub-System</code>: Zerlegt Systemextrakte weiter auf Subsystemebene.</li>\n<li><code>Develop Application Software</code>: Erstellt anwendungsspezifische Softwarekomponenten.</li>\n<li><code>Develop Basic Software</code>: Konfiguriert und generiert basisbezogene Softwaremodule.</li>\n<li><code>Integrate Software for ECU</code>: Führt alle software- und steuergerätespezifischen Artefakte auf ECU-Ebene zusammen.</li>\n<li><strong>Artefakte und Schnittstellenbeziehungen</strong>:</li>\n<li><code>Standard Package</code>: Eingang (<code>1..* «input»</code>) für <code>Develop System Description</code> (oben mittig) und <code>Develop System Description</code> (oben rechts).</li>\n<li><code>BSW Standard Package</code>: Eingang (<code>1 «input»</code>) für <code>Develop Basic Software</code>.</li>\n<li><code>System Constraint Description</code>: Optionaler Eingang (<code>0..1 «input»</code>) für <code>Develop System Description</code> (oben mittig) und <code>Develop System</code> (<code>0..1 «input»</code>).</li>\n<li><code>Abstract System Description</code>: Ausgang von <code>Develop System Description</code> (oben mittig, <code>«output» 1..<em></code>); optionaler Eingang (<code>0..</em> «input»</code>) für <code>Develop System Description</code> (oben rechts) und <code>Develop System</code> (<code>0..* «input»</code>).</li>\n<li><code>Overall VFB System</code>: Ausgang von <code>Develop System Description</code> (oben rechts, <code>«output» 1</code>); optionaler Eingang (<code>0..1 «input»</code>) für <code>Develop System</code>, Eingang (<code>1 «input»</code>) für <code>Develop Application Software</code>.</li>\n<li><code>Transformer Design Bundle</code>: Ausgang von <code>Develop System</code> (<code>«output» 0..<em></code>); dient als optionaler Eingang (<code>0..</em> «input»</code>) für <code>Develop Basic Software</code>.</li>\n<li><code>System Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 0..*</code>); Eingang (<code>1 «input»</code>) für <code>Develop Sub-System</code>.</li>\n<li><code>ECU Extract</code>: Ausgang von <code>Develop System</code> (<code>«output» 1..<em></code>) und <code>Develop Sub-System</code> (<code>«output» 1..</em></code>); Eingang (<code>1 «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>Delivered Atomic Software Components</code>: Ausgang von <code>Develop Application Software</code> (<code>«output» 1..<em></code>); Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>BSW Module Delivered Bundle</code>: Ausgang von <code>Develop Basic Software</code> (<code>«output» 1..<em></code>); Eingang (<code>1..</em> «input»</code>) für <code>Integrate Software for ECU</code>.</li>\n<li><code>ECU Software</code>: Finaler Ausgang (<code>«output» 1</code>) von <code>Integrate Software for ECU</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Entwicklungsablauf gliedert sich in folgende Sequenzphasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Systembeschreibungs- und VFB-Definition</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Develop System Description</code> (oben mittig) verarbeitet <code>Standard Package</code> und optional <code>System Constraint Description</code> zu mindestens einer <code>Abstract System Description</code>.</li>\n<li><code>Develop System Description</code> (oben rechts) verarbeitet <code>Standard Package</code> und optional <code>Abstract System Description</code> zum <code>Overall VFB System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Systemdesign, Partitionierung und Transformer-Design</strong>: <code>Develop System</code> führt optional <code>Abstract System Description</code>, <code>System Constraint Description</code> und <code>Overall VFB System</code> zusammen. Es erzeugt <code>ECU Extract</code>-Instanzen, optional <code>System Extract</code>-Instanzen sowie optional <code>Transformer Design Bundle</code>-Artefakte. <code>Develop Sub-System</code> verfeinert vorliegende <code>System Extract</code>-Artefakte zu <code>ECU Extract</code>-Instanzen.</li>\n<li><strong>Parallele Komponenten- und Basissoftwareentwicklung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Develop Application Software</code> generiert aus dem <code>Overall VFB System</code> atomare Softwarekomponenten (<code>Delivered Atomic Software Components</code>).</li>\n<li><code>Develop Basic Software</code> nutzt <code>BSW Standard Package</code> und optional <code>Transformer Design Bundle</code> zur Erstellung des <code>BSW Module Delivered Bundle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU-Integration</strong>: <code>Integrate Software for ECU</code> integriert <code>ECU Extract</code>, <code>BSW Module Delivered Bundle</code> und <code>Delivered Atomic Software Components</code> zur finalen <code>ECU Software</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Einführung des <code>Transformer Design Bundle</code> standardisiert die modellbasierte Definition von Daten-Transformationen (z. B. Serialization, SOME/IP Transformer, E2E Protection) auf Systemebene und deren Übergabe an die Basissoftwareentwicklung. Entwickler und Generatoren von BSW-Modulen (insbesondere RTE und Com-Stack) müssen Transformer-Beschreibungen verarbeiten können, sofern auf Systemebene entsprechende Transformer-Ketten modelliert wurden.</p>"}], "trans": [{"from": "FIG-7acf61c8a20ec5d0", "to": "FIG-ebbda13bbb22d49c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neue Aktivität „Develop System Description“ (oben mittig) mit Eingängen aus „Standard Package“ (1..<em>) und „System Constraint Description“ (0..1) sowie Ausgang zu „Abstract System Description“ (1..</em>).</li>\n<li>Neues Artefakt „Abstract System Description“ als optionaler/mehrfacher Eingang (0..<em>) für „Develop a VFB System Description“ und Eingang (0..</em>) für „Develop System“.</li>\n<li>Kardinalitätsänderung am Ausgang von „Develop System“ zu „System Extract“ von 1..<em> auf 0..</em>.</li>\n<li>Umbenennung der Aktivität „Develop a VFB System Description“ (in der rechten Spalte oben) zu „Develop System Description“ (bzw. Weiterverwendung als Aktivität mit Eingang „Abstract System Description“ und Standard Package) sowie Umbenennung der nachfolgenden Aktivität von „Develop Application Software“ (in R4.0.3 abgeschnitten/rechts als „Develop Application Software“ bereits angelegt, in R4.1.3 vollständig bezeichnet).</li>\n<li>Zusätzliche optionale Eingangsbeziehung (0..1) von „Overall VFB System“ in „Develop System“.</li>\n</ul>"}, {"from": "FIG-ebbda13bbb22d49c", "to": "FIG-8db5103d6653e15c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neues Artefakt „Transformer Design Bundle“ eingefügt.</li>\n<li>Neue Ausgangsbeziehung («output», 0..*) von Aktivität „Develop System“ zu „Transformer Design Bundle“.</li>\n<li>Neue Eingangsbeziehung («input», 0..*) von „Transformer Design Bundle“ in Aktivität „Develop Basic Software“.</li>\n</ul>"}]};
